var suiviPatientsElianInitial = registrePatientsElianVoss.lignes.map((ligne) => ({
  id: ligne.code,
  nom: ligne.patient,
  origine: ligne.origine,
  localisation: ligne.localisation,
  statutInitial: statutInitialPatient(ligne.localisation),
  prioriteInitiale: prioritePatient(ligne),
  piste: ligne.localisation
}));
function statutInitialPatient(localisation) {
  if (localisation.startsWith("Disparu")) return "disparu";
  return "a_localiser";
}
function prioritePatient(ligne) {
  const texte = `${ligne.resultat} ${ligne.localisation}`.toLowerCase();
  if (texte.includes("fragilit\xE9") || texte.includes("t\xE9moignage") || texte.includes("preuve") || texte.includes("confisqu\xE9") || texte.includes("dernier dossier")) {
    return "critique";
  }
  if (texte.includes("disparu") || texte.includes("d\xE9pendance") || texte.includes("danger") || texte.includes("endeuill\xE9s")) {
    return "haute";
  }
  return "normale";
}

